import { readFileSync } from 'node:fs'
import { describe, expect, it } from 'vitest'
import { bindParameters } from '../../src/query/import.ts'
import { addslashes, formatNumber, isNumeric, pregQuote, ucwords } from '../../src/util/php.ts'

/** Generated by scripts/gen-php-util.php from phpMyAdmin and PHP itself. */
const fx = JSON.parse(readFileSync(new URL('./fixtures/php-util.json', import.meta.url), 'utf8')) as {
  formatNumber: Array<[number | string, number, number, string]>
  isNumeric: Array<[string, boolean]>
  addslashes: Array<[string, string]>
  ucwords: Array<[string, string]>
  pregQuote: Array<[string, string]>
  bind: Array<[string, Record<string, string>, string]>
}

describe('PHP built-ins used by the pipeline', () => {
  it('Util::formatNumber', () => {
    for (const [n, l, r, want] of fx.formatNumber) expect(formatNumber(n, l, r), `${n} ${l} ${r}`).toBe(want)
  })
  it('is_numeric', () => {
    for (const [s, want] of fx.isNumeric) expect(isNumeric(s), JSON.stringify(s)).toBe(want)
  })
  it('addslashes', () => {
    for (const [s, want] of fx.addslashes) expect(addslashes(s)).toBe(want)
  })
  it('ucwords', () => {
    for (const [s, want] of fx.ucwords) expect(ucwords(s)).toBe(want)
  })
  it('preg_quote', () => {
    for (const [s, want] of fx.pregQuote) expect(pregQuote(s)).toBe(want)
  })
  it('bind parameters (ImportController)', () => {
    for (const [sql, params, want] of fx.bind) expect(bindParameters(sql, params), sql).toBe(want)
  })
})
